import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    TrendingUp, Award, Target, CalendarCheck, 
    Flame, Zap, Github, ExternalLink
} from 'lucide-react';
import axios from 'axios';

const Dashboard = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const [tasks, setTasks] = useState([]);

    useEffect(() => {
        if (user) {
            fetchData();
        }
    }, [user]);

    const fetchData = async () => {
        try {
            // Fetch tasks
            const tasksRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasksRes.data);

            // Fetch stats
            const statsRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(statsRes.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch data:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    // Calculate REAL stats from database
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
    const totalDays = 31; // July 2026

    // Calculate streak from real data
    const calculateStreak = () => {
        let streak = 0;
        const today = new Date();
        for (let i = 0; i < 31; i++) {
            const date = new Date(2026, 6, 31 - i);
            const dayTasks = tasks.filter(t => {
                const taskDate = new Date(t.date);
                return taskDate.getDate() === date.getDate() && 
                       taskDate.getMonth() === date.getMonth() &&
                       taskDate.getFullYear() === date.getFullYear();
            });
            if (dayTasks.length > 0 && dayTasks.every(t => t.overallCompleted)) {
                streak++;
            } else if (i > 0) {
                break;
            }
        }
        return streak;
    };

    const streak = calculateStreak();

    // Generate REAL contribution data from database
    const generateContributions = () => {
        const data = [];
        for (let day = 1; day <= 31; day++) {
            const dayTasks = tasks.filter(t => t.day === day);
            const completed = dayTasks.filter(t => t.overallCompleted).length;
            const total = dayTasks.length;
            let level = 0;
            if (total > 0 && completed === total) level = 4;
            else if (completed > 0) level = Math.min(3, Math.ceil((completed / total) * 4));
            data.push({ day, level });
        }
        return data;
    };

    const contributions = generateContributions();

    const levelColors = {
        0: 'bg-gray-100',
        1: 'bg-green-200',
        2: 'bg-green-300',
        3: 'bg-green-400',
        4: 'bg-green-600'
    };

    return (
        <div className="max-w-7xl mx-auto">
            {/* Header Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm text-gray-500">Progress</p>
                            <p className="text-2xl font-bold text-gray-800">{completionRate}%</p>
                        </div>
                        <div className="bg-blue-50 p-3 rounded-lg">
                            <TrendingUp className="text-blue-600" size={24} />
                        </div>
                    </div>
                </div>
                
                <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm text-gray-500">Days Done</p>
                            <p className="text-2xl font-bold text-gray-800">{completedTasks}/{totalDays}</p>
                        </div>
                        <div className="bg-green-50 p-3 rounded-lg">
                            <CalendarCheck className="text-green-600" size={24} />
                        </div>
                    </div>
                </div>
                
                <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm text-gray-500">Streak</p>
                            <p className="text-2xl font-bold text-gray-800">{streak} days</p>
                        </div>
                        <div className="bg-orange-50 p-3 rounded-lg">
                            <Flame className="text-orange-600" size={24} />
                        </div>
                    </div>
                </div>
                
                <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-sm text-gray-500">Target</p>
                            <p className="text-2xl font-bold text-gray-800">{totalDays} days</p>
                        </div>
                        <div className="bg-purple-50 p-3 rounded-lg">
                            <Target className="text-purple-600" size={24} />
                        </div>
                    </div>
                </div>
            </div>

            {/* GitHub Style Contribution Graph */}
            <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100 mb-6">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2">
                        <Github size={20} className="text-gray-600" />
                        <h3 className="font-semibold text-gray-800">July 2026 Activity</h3>
                    </div>
                    <span className="text-sm text-gray-500">
                        {completedTasks} of {totalTasks} tasks completed
                    </span>
                </div>
                
                <div className="grid grid-cols-7 gap-1.5">
                    {contributions.map((item, index) => (
                        <div
                            key={index}
                            className={`aspect-square rounded-sm ${levelColors[item.level]}`}
                            title={`Day ${item.day}: ${item.level} tasks`}
                        />
                    ))}
                </div>
                
                <div className="flex items-center justify-between mt-3">
                    <div className="flex items-center gap-2 text-xs text-gray-500">
                        <span>Less</span>
                        <div className="flex gap-1">
                            <div className="w-3 h-3 bg-gray-100 rounded-sm"></div>
                            <div className="w-3 h-3 bg-green-200 rounded-sm"></div>
                            <div className="w-3 h-3 bg-green-300 rounded-sm"></div>
                            <div className="w-3 h-3 bg-green-400 rounded-sm"></div>
                            <div className="w-3 h-3 bg-green-600 rounded-sm"></div>
                        </div>
                        <span>More</span>
                    </div>
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="text-sm text-blue-600 hover:text-blue-800 flex items-center gap-1"
                    >
                        View details <ExternalLink size={14} />
                    </button>
                </div>
            </div>

            {/* Quick Actions */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-gradient-to-r from-blue-500 to-blue-600 rounded-xl shadow-sm p-6 text-white">
                    <h4 className="font-semibold mb-1">📝 Log Today</h4>
                    <p className="text-blue-100 text-sm mb-3">Track your daily progress</p>
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm transition"
                    >
                        Go to Tracker →
                    </button>
                </div>
                
                <div className="bg-gradient-to-r from-purple-500 to-purple-600 rounded-xl shadow-sm p-6 text-white">
                    <h4 className="font-semibold mb-1">📚 Your Roadmap</h4>
                    <p className="text-purple-100 text-sm mb-3">View your 4-month plan</p>
                    <button 
                        onClick={() => window.location.href = '/weekly-focus'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm transition"
                    >
                        View Roadmap →
                    </button>
                </div>
                
                <div className="bg-gradient-to-r from-green-500 to-green-600 rounded-xl shadow-sm p-6 text-white">
                    <h4 className="font-semibold mb-1">📊 Analytics</h4>
                    <p className="text-green-100 text-sm mb-3">See your progress stats</p>
                    <button 
                        onClick={() => window.location.href = '/progress'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm transition"
                    >
                        View Analytics →
                    </button>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
